default = "DEFAULT"


class PduVersionedModel(object):
    def __init__(self, devices: Union[Type[PDU_TYPE], Dict[str, Type[PDU_TYPE]]]) -> None:
        if isinstance(devices, dict):
            self.available_devices = devices
        else:
            self.available_devices = {default: devices}

    def get_versioned_model(self, version: str) -> Type[PDU_TYPE]:
        if not version:
            version = default
        versioned_model = self.available_devices.get(version.upper()) or self.available_devices.get(version)
        if versioned_model:
            return versioned_model
        raise DeviceNotSupported(f"Version {version} is not supported")


class PduVendor(object):
    def __init__(self, models: Union[PduVersionedModel, Dict[str, PduVersionedModel]]) -> None:
        if isinstance(models, dict):
            self.available_models = models
        else:
            self.available_models = {default: models}

    def get_model(self, model: str) -> PduVersionedModel:
        try:
            if model:
                model = model.upper()
            else:
                model = default
            pdu_model = self.available_models[model]
            return pdu_model
        except KeyError:
            raise DeviceNotSupported(f"Model {model} is not supported")


