class SupportedPduVendors(object):
    """
    The purpose of this class is to map vendors to their
    respective PDU model(s).

    For example, the following code will map a GUDE vendor to the
    EPC PDU model that is accessible either by the "EPC" string or
    by "DEFAULT" string:
    ```
    GUDE = PduVendor({'EPC': VersionedModels.EPC,
                     default: VersionedModels.EPC})
    epc = GUDE.get_model('EPC')
    epc = GUDE.get_model('DEFAULT')
    ```

    If the Vendor input is not a dictionary, it is assumed that it's model
    is accessible only by the "DEFAULT" string.
    """

    ATEN = PduVendor(VersionedModels.ATEN_DEFAULT)
    APP6 = PduVendor({default: VersionedModels.APP6, "MULTI": VersionedModels.APP6})
    SWH = PduVendor(VersionedModels.SWH_DEFAULT)
    BLACKBOX = PduVendor(VersionedModels.BLACKBOX_DEFAULT)
    FACOM = PduVendor(VersionedModels.FACOM_DEFAULT)
    RRB = PduVendor(VersionedModels.RRB_DEFAULT)
    APC = PduVendor(VersionedModels.APC)
    PKC = PduVendor({"PKC": VersionedModels.PKC, default: VersionedModels.PKC})
    UTRONIX = PduVendor(VersionedModels.UTRONIX_DEFAULT)
    OSP = PduVendor(VersionedModels.OSP_DEFAULT)
    GUDE = PduVendor(
        {
            "EPC": VersionedModels.EPC,
            "ENC": VersionedModels.ENC,
            default: VersionedModels.EPC,
        }
    )
    EPC = GUDE  # TODO: Deprecated. Remove this line in 2.0.0
    ENICS = PduVendor({"ENICS": VersionedModels.ENICS, default: VersionedModels.ENICS})
    HBTE = PduVendor(VersionedModels.HBTE)
    FPFH = PduVendor(VersionedModels.FPFH_DEFAULT)
    DIGIPOWER = PduVendor(VersionedModels.DIGIPOWER_DEFAULT)
    LANTICK = PduVendor(VersionedModels.LANTICK_DEFAULT)
    TOPYOUNG = PduVendor(
        {
            "RTS-C003-186": VersionedModels.TOPYOUNGRTSC003186,
            default: VersionedModels.TOPYOUNG_DEFAULT,
        }
    )
    TDKLAMBDA = PduVendor(VersionedModels.TDKLAMBDA_DEFAULT)
    PS9000 = PduVendor(VersionedModels.PS9000_DEFAULT)
    JIEXI = TOPYOUNG
    HPE = PduVendor(VersionedModels.HPE)
    DELTA = PduVendor(VersionedModels.DELTA)
    DELTA_ELEKTRONIKA = PduVendor(VersionedModels.DELTA_ELEKTRONIKA)
    ICT = PduVendor(VersionedModels.ICT)
    HAOJIN = PduVendor(VersionedModels.HAOJIN)
    DURACOMM = PduVendor(VersionedModels.DURACOMM)
    PSU = PduVendor(VersionedModels.PSU_DEFAULT)
    CREOTECH = PduVendor(VersionedModels.CREOTECH_DEFAULT)
    BKT = PduVendor(VersionedModels.BKT_DEFAULT)
    IPOWER = PduVendor(
        {
            "IT-101-IP4-3H": VersionedModels.IPOWER_DEFAULT,
            "IT-010-IP4-3H": VersionedModels.IPOWER_DEFAULT,
            "IT-010-IP3-3H": VersionedModels.IPOWER_DEFAULT,
            default: VersionedModels.IPOWER_DEFAULT,
        }
    )
    FAC = PduVendor(VersionedModels.FAC)
    EPCNC = PduVendor(VersionedModels.EPCNC)
    ORBIS = PduVendor(VersionedModels.ORBIS)
    KEYSIGHT = PduVendor(VersionedModels.KEYSIGHT)
    ELEKTRO_AUTOMATIK = PduVendor(VersionedModels.ElektroAutomatik)
    KIKUSUI = PduVendor(VersionedModels.KIKUSUI_DEFAULT)
    ZENTRONICS = PduVendor(VersionedModels.ZENTRONICS)

    @classmethod
    def get_vendor(cls, vendor: str) -> PduVendor:
        try:
            vendor_type = getattr(cls, vendor.upper())
            return vendor_type
        except AttributeError:
            raise DeviceNotSupported(f"Vendor {vendor} is not supported")
